import numpy as np

def simulate_v2(c_seq):
    num_points = 50
    points = np.linspace(0, 1, num_points, endpoint=False)

    # Ronaldo wants to avoid covering.
    # We want to see if there's a sequence c_i such that Ronaldo is forced to cover.
    # This is a minimax problem.
    # Since the sequence is infinite, we'll use a finite number of steps.
    # For a fixed sequence, Ronaldo can avoid it if there is a path in the state space.

    memo = {}

    def can_ronaldo_avoid(idx, cur_x, covered_mask):
        state = (idx, round(cur_x, 4), tuple(covered_mask))
        if state in memo: return memo[state]

        if idx == len(c_seq):
            return not np.all(covered_mask)

        c = c_seq[idx]
        # Ronaldo's turn
        # Try both directions
        for s in [1, -1]:
            x_new = (cur_x + s * c) % 1
            new_mask = covered_mask.copy()
            if s == 1:
                if cur_x <= x_new:
                    mask_indices = (points >= cur_x - 1e-7) & (points <= x_new + 1e-7)
                else:
                    mask_indices = (points >= cur_x - 1e-7) | (points <= x_new + 1e-7)
            else:
                if x_new <= cur_x:
                    mask_indices = (points >= x_new - 1e-7) & (points <= cur_x + 1e-7)
                else:
                    mask_indices = (points >= x_new - 1e-7) | (points <= cur_x + 1e-7)
            new_mask[mask_indices] = True

            if can_ronaldo_avoid(idx + 1, x_new, new_mask):
                memo[state] = True
                return True

        memo[state] = False
        return False

    return can_ronaldo_avoid(0, 0.0, np.zeros(num_points, dtype=bool))

